#define RESOLUTION vec2(192., 108.)
#define HORIZON 64.
#define LARGEUR 1.1
#define VITESSE 16.
#define PAS 3.
#define DEPART 3.
#define ARRIVEE 38.
#define DUREE 60.
#define LIGNE (VITESSE*(ARRIVEE - DEPART - .6) + .8)

const vec3 BRUME = vec3(.99, .82, .90);

const int GLYPHE_0 = 075557; const int GLYPHE_1 = 026227; const int GLYPHE_2 = 071747;
const int GLYPHE_3 = 071717; const int GLYPHE_4 = 055711; const int GLYPHE_S = 074717;
const int GLYPHE_T = 072222; const int GLYPHE_N = 057755; const int GLYPHE_D = 065556;
const int GLYPHE_R = 075765; const int GLYPHE_H = 055755; const int GLYPHE_V = 055552;
const int GLYPHE_I = 072227; const int GLYPHE_C = 074447; const int GLYPHE_E = 074747;
const int GLYPHE_G = 074557; const int GLYPHE_INTERROGATION = 071302;

const float MATRICE_BAYER[16] = float[16](0.,8.,2.,10.,12.,4.,14.,6.,3.,11.,1.,9.,15.,7.,13.,5.);

float hasard1(float n){ return fract(sin(n*127.1)*43758.5453); }
float hasard2(vec2 q){ return fract(sin(dot(q, vec2(12.9898, 78.233)))*43758.5453); }

float seuilBayer(vec2 p){
    int i = int(mod(p.x, 4.)) + 4*int(mod(p.y, 4.));
    return (MATRICE_BAYER[i] + .5)/16.;
}
float tramage(float f, vec2 p){ return clamp(floor(f*5. + seuilBayer(p))/5., 0., 1.); }
float facteurBrume(float d){ return 1. - smoothstep(1., 22., d); }

bool boite(vec2 l, float x0, float y0, float x1, float y1)
{
    return l.x >= x0 && l.x <= x1 && l.y >= y0 && l.y <= y1;
}

float distSegment(vec2 p, vec2 a, vec2 b)
{
    vec2 pa = p - a, ba = b - a;
    float h = clamp(dot(pa, ba)/dot(ba, ba), 0., 1.);
    return length(pa - ba*h);
}

bool dansTriangle(vec2 p, vec2 a, vec2 b, vec2 c)
{
    vec2 v0 = c - a, v1 = b - a, v2 = p - a;
    float d00 = dot(v0, v0), d01 = dot(v0, v1), d11 = dot(v1, v1);
    float d20 = dot(v2, v0), d21 = dot(v2, v1);
    float den = d00*d11 - d01*d01;
    float v = (d11*d20 - d01*d21)/den;
    float w = (d00*d21 - d01*d20)/den;
    return v >= 0. && w >= 0. && v + w <= 1.;
}

bool dansCoeur(vec2 q, float taille)
{
    vec2 v = q/taille;
    v.y += .25;
    float a = v.x*v.x + v.y*v.y - 1.;
    return a*a*a - v.x*v.x*v.y*v.y*v.y < 0.;
}

float glyphe(int g, vec2 c)
{
    if(c.x < 0. || c.x > 2. || c.y < 0. || c.y > 4.) return 0.;
    int bit = int(c.y)*3 + 2 - int(c.x);
    return float((g >> bit) & 1);
}
float caractere(vec2 p, vec2 o, float echelle, int g){ return glyphe(g, floor((p - o)/echelle)); }

int glypheChiffre(int n)
{
    if(n == 1) return GLYPHE_1;
    if(n == 2) return GLYPHE_2;
    if(n == 3) return GLYPHE_3;
    if(n == 4) return GLYPHE_4;
    return GLYPHE_0;
}

float texteRang(vec2 p, int classement)
{
    vec2 o = vec2(148., 90.);
    int g2 = (classement == 2) ? GLYPHE_N : ((classement == 3) ? GLYPHE_R : ((classement == 4) ? GLYPHE_T : GLYPHE_S));
    int g3 = (classement == 1) ? GLYPHE_T : ((classement == 4) ? GLYPHE_H : GLYPHE_D);
    return caractere(p, o, 3., glypheChiffre(classement)) + caractere(p, o + vec2(12., 0.), 3., g2) + caractere(p, o + vec2(24., 0.), 3., g3);
}

float texteVictoire(vec2 p, vec2 o, float e)
{
    return caractere(p, o, e, GLYPHE_V) + caractere(p, o + vec2(4.*e, 0.), e, GLYPHE_I)
         + caractere(p, o + vec2(8.*e, 0.), e, GLYPHE_C) + caractere(p, o + vec2(12.*e, 0.), e, GLYPHE_T)
         + caractere(p, o + vec2(16.*e, 0.), e, GLYPHE_0) + caractere(p, o + vec2(20.*e, 0.), e, GLYPHE_I)
         + caractere(p, o + vec2(24.*e, 0.), e, GLYPHE_R) + caractere(p, o + vec2(28.*e, 0.), e, GLYPHE_E);
}

float comptage(vec2 p, float temps, float centreX)
{
    if(temps < DEPART)
        return caractere(p, vec2(centreX - 9., 50.), 6., glypheChiffre(3 - int(floor(temps))));
    if(temps < DEPART + 1.2)
        return caractere(p, vec2(centreX - 21., 50.), 6., GLYPHE_G) + caractere(p, vec2(centreX + 3., 50.), 6., GLYPHE_0);
    return 0.;
}

vec3 teinteComptage(float temps)
{
    if(temps < 1.) return vec3(1., .45, .50);
    if(temps < 2.) return vec3(1., .85, .40);
    return vec3(.55, .95, .65);
}

float courbe(float z)
{
    float amplitude = smoothstep(15., 60., z)*(1. - smoothstep(LIGNE - 90., LIGNE - 30., z));
    return amplitude*(12.*sin(z*.05) + 4.*sin(z*.11 + 1.3));
}

float ecartRoute(float z, float trajet, float base, float pente)
{
    return courbe(z) - base - pente*(z - trajet);
}

float lateralHeros(float trajet)
{
    float calme = 1. - smoothstep(LIGNE - 60., LIGNE - 10., trajet);
    return calme*(.3*sin(trajet*.043) + .12*sin(trajet*.11 + 1.));
}

float lateralSlime(float indice, float instant){ return (hasard1(indice*3.7) - .5)*1.2 + .35*sin(instant*2.2 + indice); }

float trajetTemps(float t)
{
    float s = t - DEPART;
    float d = (s < 0.) ? 0. : ((s < 1.2) ? s*s/2.4 : s - .6);
    d *= VITESSE;
    if(t > ARRIVEE){
        float u = clamp((t - ARRIVEE)/2.5, 0., 1.);
        d = VITESSE*(ARRIVEE - DEPART - .6) + 20.*(1. - (1. - u)*(1. - u));
    }
    return d;
}

vec4 profilRival(int r)
{
    if(r == 0) return vec4(5.5, 9., -1., 0.);
    if(r == 1) return vec4(8., 17., 1., 1.);
    return vec4(11.5, 26., -1., 2.);
}

float zRelatifRival(int r, float tj)
{
    vec4 profil = profilRival(r);
    float lineaire = .8 + (profil.x - .8)*(1. - tj/profil.y);
    float frappe = profil.y - 4.5;
    float freinage = 1.2*smoothstep(frappe, frappe + 1.5, tj);
    return lineaire - freinage + .12*sin(tj*1.3 + profil.w*2.);
}

float lateralRival(int r, float tj, float zRelatif, float posHeros)
{
    vec4 profil = profilRival(r);
    float base = .55*sin(tj*.55 + profil.w*2.4) + (profil.w - 1.)*.12;
    float zone = 1. - smoothstep(1.4, 2.8, zRelatif);
    float cible = posHeros + profil.z*.8;
    float frappe = profil.y - 4.5;
    float lat = mix(base, cible, zone) + profil.z*.35*smoothstep(frappe, frappe + .5, tj);
    return clamp(lat, -.92, .92);
}

vec4 spriteArbre(vec2 q, float h)
{
    if(q.x < -15. || q.x > 15. || q.y < 0. || q.y > 38.) return vec4(0.);
    if(q.x >= -1.5 && q.x <= 1.5 && q.y < 14.){
        vec3 tronc = vec3(.86, .62, .50);
        if(q.x < -.5) tronc = vec3(.95, .74, .60);
        return vec4(tronc, 1.);
    }
    vec2 c1 = q - vec2(0., 24.);
    vec2 c2 = q - vec2(-8., 19.);
    vec2 c3 = q - vec2(8., 19.);
    float d = min(length(c1) - 10.5, min(length(c2) - 5.5, length(c3) - 5.5));
    if(d < 0. && q.y >= 13.){
        vec3 feuillage = (h < .33) ? vec3(.60, .90, .70) : ((h < .66) ? vec3(1., .75, .84) : vec3(1., .85, .66));
        vec3 ombre = feuillage*vec3(.82, .80, .90);
        vec3 c = mix(ombre, feuillage, clamp(.5 - q.x*.03 + (q.y - 24.)*.03, 0., 1.));
        if(d > -1.) c *= .88;
        if(boite(q, -4., 23., -3., 25.) || boite(q, 3., 23., 4., 25.)) c = vec3(.18, .10, .25);
        if(boite(q, -4., 25., -4., 25.) || boite(q, 3., 25., 3., 25.)) c = vec3(1.);
        if(boite(q, -6., 20., -5., 21.) || boite(q, 5., 20., 6., 21.)) c = vec3(1., .55, .68);
        if(boite(q, -1., 21., -1., 21.) || boite(q, 1., 21., 1., 21.) || boite(q, 0., 20., 0., 20.)) c = vec3(.55, .22, .32);
        if(length(q - vec2(-5., 29.)) < 1.6) c = vec3(1., .98, .98);
        return vec4(c, 1.);
    }
    return vec4(0.);
}

vec4 spriteLampadaire(vec2 q, float temps)
{
    if(q.x < -8. || q.x > 8. || q.y < 0. || q.y > 36.) return vec4(0.);
    if(q.x >= -1. && q.x <= 0. && q.y < 22.)
        return vec4((mod(floor(q.y/2.), 2.) < 1.) ? vec3(1., .62, .78) : vec3(1., .97, .98), 1.);
    vec2 d = q - vec2(0., 28.);
    float r = length(d);
    if(r < 7.){
        float a = atan(d.y, d.x);
        vec3 c = (fract(a/6.2832 + r*.14 - temps*.15) < .5) ? vec3(1., .55, .75) : vec3(1., .96, .98);
        if(r > 6.) c = vec3(1., .45, .68);
        if(length(d - vec2(-2.5, 2.5)) < 1.2) c = vec3(1.);
        return vec4(c, 1.);
    }
    return vec4(0.);
}

vec4 spriteBoite(vec2 q, float temps)
{
    if(q.x < -6. || q.x > 5. || q.y < 0. || q.y > 11.) return vec4(0.);
    bool bordure = q.x < -5. || q.x > 4. || q.y < 1. || q.y > 10.;
    vec3 c = bordure ? vec3(1.) : (.55 + .45*cos(temps*4. + q.y*.5 + q.x*.3 + vec3(0., 2., 4.)));
    vec2 qGlyphe = floor((q - vec2(-3., 1.))/2.);
    if(!bordure && glyphe(GLYPHE_INTERROGATION, qGlyphe) > .5) c = vec3(1.);
    return vec4(c, 1.);
}

vec4 spriteSlime(vec2 q, float saut, float variante, float temps)
{
    q.y -= saut;
    if(abs(q.x) > 10. || q.y < -1. || q.y > 18.) return vec4(0.);
    float ecrasement = .22*(1. - clamp(saut/5., 0., 1.));
    vec2 e = (q - vec2(0., 5.*(1. - ecrasement)))/vec2(8.*(1. + ecrasement), 5.5*(1. - ecrasement));
    vec4 c = vec4(0.);
    if(dot(e, e) < 1. && q.y >= 0.){
        float g = clamp(e.y*.5 + .5, 0., 1.);
        vec3 b = variante < .5 ? mix(vec3(.55, .92, .75), vec3(.82, 1., .90), g)
                           : mix(vec3(1., .68, .80), vec3(1., .88, .92), g);
        if(dot(e, e) > .72) b = variante < .5 ? vec3(.35, .70, .55) : vec3(.88, .45, .62);
        if(length(q - vec2(-3.5, 8.)) < 1.4) b = vec3(1.);
        c = vec4(b, 1.);
    }
    if(variante < .5){
        if(boite(q, -1., 10., 0., 12.)) c = vec4(.45, .75, .40, 1.);
        if(length(q - vec2(-2.5, 12.5)) < 1.8 || length(q - vec2(2.5, 12.5)) < 1.8) c = vec4(.55, .88, .45, 1.);
    } else {
        if(boite(q, -4., 11., -2., 13.) || boite(q, 2., 11., 4., 13.)) c = vec4(1., .35, .55, 1.);
        if(boite(q, -1., 11., 1., 12.)) c = vec4(.95, .25, .45, 1.);
    }
    if(c.a > .5){
        vec3 joue = variante < .5 ? vec3(1., .62, .72) : vec3(1., .42, .58);
        if(length((q - vec2(-3., 6.))/vec2(1.7, 2.2)) < 1. || length((q - vec2(3., 6.))/vec2(1.7, 2.2)) < 1.) c = vec4(.14, .08, .22, 1.);
        if(length(q - vec2(-3.5, 7.)) < .7 || length(q - vec2(2.5, 7.)) < .7) c = vec4(1.);
        if(length(q - vec2(-2.5, 5.)) < .45 || length(q - vec2(3.5, 5.)) < .45) c = vec4(1.);
        if(length((q - vec2(-5.8, 3.5))/vec2(1.4, 1.)) < 1. || length((q - vec2(5.8, 3.5))/vec2(1.4, 1.)) < 1.) c = vec4(joue, 1.);
        if(boite(q, -1., 3., -1., 3.) || boite(q, 0., 2., 0., 2.) || boite(q, 1., 3., 1., 3.)) c = vec4(.55, .22, .32, 1.);
    }
    return c;
}

vec4 spriteDragon(vec2 q, float t)
{
    if(q.x < -24. || q.x > 42. || q.y < -12. || q.y > 26.) return vec4(0.);
    vec4 c = vec4(0.);
    float battement = sin(t*5.);
    vec3 vert = vec3(.62, .92, .78);
    vec3 ventre = vec3(1., .88, .70);

    vec2 b0 = vec2(0., 4.);
    vec2 w1 = vec2(-6., 4. + 14.*battement);
    vec2 w2 = vec2(-13., 3. + 5.*battement);
    if(dansTriangle(q, b0, w1, w2)) c = vec4(1., .72, .88, 1.);
    if(distSegment(q, b0, w1) < .8 || distSegment(q, b0, w2) < .7) c = vec4(1., .55, .78, 1.);

    float bout = -4. + 3.*sin(t*3.);
    if(distSegment(q, vec2(-5., 0.), vec2(-16., bout)) < 1.8) c = vec4(vert, 1.);
    if(dansCoeur(q - vec2(-18., bout), 3.)) c = vec4(1., .45, .65, 1.);
    if(length(q - vec2(-2., -6.)) < 2.4 || length(q - vec2(4., -6.)) < 2.4) c = vec4(vert, 1.);
    if(length((q - vec2(0., 0.))/vec2(8., 6.)) < 1.) c = vec4(vert, 1.);
    if(length((q - vec2(1., -1.5))/vec2(5.5, 3.8)) < 1.) c = vec4(ventre, 1.);
    if(length(q - vec2(10., 6.)) < 6.2) c = vec4(vert, 1.);
    if(length(q - vec2(15.5, 4.5)) < 3.) c = vec4(vert, 1.);
    if(dansTriangle(q, vec2(7., 11.), vec2(9.5, 11.), vec2(8., 15.)) || dansTriangle(q, vec2(10.5, 11.), vec2(13., 11.), vec2(12.5, 15.))) c = vec4(1., .95, .70, 1.);
    if(length((q - vec2(12.5, 7.5))/vec2(1.4, 1.9)) < 1.) c = vec4(.14, .08, .22, 1.);
    if(length(q - vec2(13., 8.5)) < .6) c = vec4(1.);
    if(length((q - vec2(14., 3.5))/vec2(1.8, 1.1)) < 1.) c = vec4(1., .62, .72, 1.);
    if(length(q - vec2(17.8, 5.)) < .6) c = vec4(.55, .30, .35, 1.);

    for(int i = 0; i < 3; i++){
        float k = fract(t*.5 + float(i)/3.);
        vec2 pos = vec2(19. + k*20., 5. + 4.*sin(k*6. + float(i)));
        if(dansCoeur(q - pos, 1.5 + k*1.5)) c = vec4(mix(vec3(1., .55, .75), vec3(1., .85, .50), float(i)/2.), 1.);
    }
    return c;
}

vec4 kartDeDos(vec2 l, int pilote, vec3 carrosserie, float temps, float inclinaison, float rotation, float turbo, float regard)
{
    if(l.x < -22. || l.x > 22. || l.y < 0. || l.y > 44.) return vec4(0.);
    vec2 u = vec2(l.x - inclinaison*l.y*.09, l.y);
    vec4 c = vec4(0.);

    if(pilote == 0){
        float sensTete = (regard >= 0.) ? 1. : -1.;
        float decalageTete = floor(regard*2.5 + .5);
        vec2 uh = vec2(floor(u.x + .5), u.y);
        vec2 th = vec2(uh.x - decalageTete, uh.y);

        if(boite(u, -5., 12., 5., 20.)){
            vec3 tunique = vec3(.20, .38, .80)*(.85 + .3*step(0., u.x));
            if(abs(u.y - 15.) < .5) tunique = vec3(.62, .42, .16);
            c = vec4(tunique, 1.);
        }
        if(boite(u, -7., 15., -6., 20.) || boite(u, 6., 15., 7., 20.)) c = vec4(.17, .32, .70, 1.);
        if(distSegment(u, vec2(-5., 13.), vec2(5., 21.)) < .9 && abs(u.x) < 6.) c = vec4(.35, .22, .14, 1.);
        if(distSegment(u, vec2(4., 21.), vec2(7., 24.5)) < .6) c = vec4(.50, .30, .20, 1.);
        if(distSegment(u, vec2(5.2, 23.6), vec2(9., 22.2)) < .6) c = vec4(.95, .75, .30, 1.);
        if(length(u - vec2(7.6, 25.6)) < 1.3) c = vec4(.95, .75, .30, 1.);

        if(boite(th, -4., 21., 4., 27.)){
            vec3 peau = vec3(.97, .90, .78);
            if(th.y < 22.) peau = vec3(.82, .72, .60);
            c = vec4(peau, 1.);
        }
        if(abs(regard) < .3){
            if(boite(th, -5., 24., -5., 25.) || boite(th, 5., 24., 5., 25.)) c = vec4(1., .60, .65, 1.);
        } else {
            vec2 tp = vec2(th.x*sensTete, th.y);
            if(boite(tp, 4., 24., 5., 25.)) c = vec4(.88, .70, .58, 1.);
            if(boite(tp, 2., 24., 3., 26.)) c = vec4(.08, .05, .12, 1.);
            if(boite(tp, 2., 26., 2., 26.)) c = vec4(1.);
            if(boite(tp, 3., 22., 4., 22.)) c = vec4(1., .60, .65, 1.);
        }

        vec2 pc = vec2(th.x, u.y);
        vec2 cq = (pc - vec2(0., 34.))/vec2(10.5, 6.8);
        if(dot(cq, cq) < 1. && u.y >= 28.){
            vec3 teinteChapeau = mix(vec3(.55, .08, .25), vec3(.95, .30, .45), clamp((u.y - 28.)/12., 0., 1.));
            if(u.y < 29.) teinteChapeau = vec3(.40, .06, .20);
            vec2 s1 = pc - vec2(-4.9, 36.4);
            vec2 s2 = pc - vec2(3.7, 37.7);
            vec2 s3 = pc - vec2(0., 31.6);
            vec2 s4 = pc - vec2(7.3, 32.8);
            if(dot(s1,s1) < 4.8 || dot(s2,s2) < 3.9 || dot(s3,s3) < 2.2 || dot(s4,s4) < 1.6) teinteChapeau = vec3(.99, .95, .85);
            c = vec4(teinteChapeau, 1.);
        }
    } else if(pilote == 1){
        if(boite(u, -5., 12., 5., 19.)) c = vec4(.55, .80, .95, 1.);
        vec2 tete = u - vec2(0., 25.);
        if(dot(tete, tete) < 28.){
            c = vec4(mix(vec3(.55, .88, .58), vec3(.75, .98, .72), clamp(tete.y*.1 + .5, 0., 1.)), 1.);
        }
        for(int s = -1; s <= 1; s += 2){
            float ex = u.x*float(s);
            if(ex >= 4.5 && ex <= 11. && abs(u.y - 26.) < (11.5 - ex)*.5 + .3){
                c = vec4(.55, .88, .58, 1.);
                if(ex >= 6. && ex <= 9. && abs(u.y - 26.) < (9. - ex)*.4) c = vec4(1., .70, .78, 1.);
            }
        }
        if(dot(tete, tete) < 28. && u.y > 26.5) c = vec4(1., .62, .78, 1.);
        if(length(u - vec2(0., 32.5)) < 2.2) c = vec4(1., .97, .98, 1.);
    } else if(pilote == 2){
        vec2 fantome = (u - vec2(0., 20.))/vec2(6.5, 9.);
        float basFantome = 13. + 1.2*sin(u.x*1.6 + temps*8.);
        if(dot(fantome, fantome) < 1. && u.y >= basFantome){
            c = vec4(mix(vec3(.84, .84, .96), vec3(1., .98, 1.), clamp(.5 - u.x*.06 + (u.y - 20.)*.03, 0., 1.)), 1.);
        }
        if(boite(u, -7., 18., -6., 20.) || boite(u, 6., 18., 7., 20.)) c = vec4(1., .62, .75, 1.);
        if(boite(u, -4., 27., -2., 29.) || boite(u, 2., 27., 4., 29.)) c = vec4(1., .45, .65, 1.);
        if(boite(u, -1., 27., 1., 28.)) c = vec4(.90, .30, .50, 1.);
    } else {
        if(boite(u, -5., 12., 5., 19.)) c = vec4(1., .72, .80, 1.);
        vec2 tete = u - vec2(0., 25.);
        if(dot(tete, tete) < 31.){
            c = vec4(mix(vec3(1., .50, .52), vec3(1., .72, .66), clamp(tete.y*.1 + .5, 0., 1.)), 1.);
        }
        for(int s = -1; s <= 1; s += 2){
            float fs = float(s);
            if(distSegment(u, vec2(3.*fs, 29.), vec2(5.*fs, 33.)) < 1.3) c = vec4(1., .95, .70, 1.);
        }
        if(distSegment(u, vec2(5., 15.), vec2(10., 19.)) < .6) c = vec4(.85, .40, .60, 1.);
        if(dansCoeur(u - vec2(11., 21.), 2.2)) c = vec4(1., .35, .55, 1.);
    }

    for(int i = 0; i < 2; i++){
        float s = (i == 0) ? -1. : 1.;
        vec2 w = vec2(s*14.5, 5.5);
        vec2 d = u - w;
        if(abs(d.x) <= 3.2 && abs(d.y) <= 5.7 && !(abs(d.x) > 2.6 && abs(d.y) > 5.0)){
            vec3 t = vec3(.20, .17, .28);
            if(mod(floor(u.y + rotation), 3.) < 1.) t = vec3(.32, .28, .42);
            if(d.x*s > 1.8) t = vec3(.62, .52, .72);
            c = vec4(t, 1.);
        }
    }

    if(boite(u, -11., 3., 11., 12.)){
        vec3 b = carrosserie*mix(.65, 1.25, (u.y - 3.)/9.);
        if(dansCoeur(u - vec2(0., 8.), 2.6)) b = vec3(1., .96, .98);
        if(u.y < 4.) b = carrosserie*.45;
        if(u.y >= 10. && u.y < 11. && abs(u.x) < 4.) b = vec3(1., .35, .50);
        c = vec4(b, 1.);
    }
    if(boite(u, -13., 10., -12., 15.) || boite(u, 12., 10., 13., 15.)) c = vec4(carrosserie*1.1, 1.);

    for(int i = 0; i < 2; i++){
        float s = (i == 0) ? -1. : 1.;
        vec2 posPot = vec2(s*5.5, 5.);
        float r = length(u - posPot);
        float rayonFlamme = 1.4 + turbo*2.2;
        if(r < 2.4) c = vec4(.12, .12, .16, 1.);
        if(r < rayonFlamme) c = vec4(mix(vec3(1., .65, .80), vec3(1., .95, .70), fract(temps*17. + s)), 1.);
    }
    return c;
}

vec4 spriteProjectile(vec2 q, float genre, float temps)
{
    if(abs(q.x) > 9. || q.y < -2. || q.y > 15.) return vec4(0.);
    vec2 d = q - vec2(0., 6.);
    if(genre < .5){
        if(dansCoeur(d, 5.)){
            vec3 c = vec3(1., .40, .62);
            if(length(d - vec2(-2.5, 3.)) < 1.5) c = vec3(1.);
            return vec4(c, 1.);
        }
    } else {
        float angle = atan(d.y, d.x) + temps*6.;
        float rayon = length(d);
        if(rayon < 6.*(.58 + .42*cos(angle*5.))){
            vec3 c = vec3(1., .88, .30);
            if(rayon < 2.) c = vec3(1., .98, .70);
            return vec4(c, 1.);
        }
    }
    return vec4(0.);
}

vec4 spriteCoupe(vec2 q, float temps)
{
    if(q.x < -10. || q.x > 10. || q.y < 0. || q.y > 18.) return vec4(0.);
    vec3 doree = vec3(1., .82, .25);
    vec3 ombre = vec3(.78, .55, .12);
    vec3 lumiere = vec3(1., .97, .70);
    if(boite(q, -4., 0., 4., 1.)) return vec4((q.y < .5) ? ombre : doree, 1.);
    if(boite(q, -1., 2., 1., 6.)) return vec4(doree, 1.);
    if(q.y >= 7. && q.y <= 16.){
        float w = 3.5 + (q.y - 7.)*.5;
        if(abs(q.x) <= w){
            vec3 c = doree;
            if(q.x < -w + 1.5) c = lumiere;
            if(q.x > w - 1.) c = ombre;
            if(q.y >= 16.) c = lumiere;
            if(abs(q.x) + abs(q.y - 11.5) < 2.) c = vec3(.90, .15, .25);
            return vec4(c, 1.);
        }
        float ex = abs(q.x) - w;
        if(ex > 0. && ex <= 2.5 && q.y >= 9. && q.y <= 14. && (ex > 1.5 || q.y < 10. || q.y > 13.)) return vec4(ombre, 1.);
    }
    return vec4(0.);
}

vec4 spritePrincesse(vec2 q, float marche, float salut)
{
    if(q.x < -16. || q.x > 16. || q.y < 0. || q.y > 48.) return vec4(0.);
    vec4 c = vec4(0.);
    vec3 peau = vec3(.99, .91, .80);
    vec3 blond = vec3(1., .82, .28);

    vec2 qc = (q - vec2(0., 31.))/vec2(8.5, 13.);
    if(dot(qc, qc) < 1. && q.y < 44.) c = vec4(blond*(.85 + .15*step(q.x, 0.)), 1.);

    if(q.y >= 6. && q.y <= 24.){
        float w = 5. + (24. - q.y)*.5;
        if(abs(q.x) <= w){
            vec3 r = mix(vec3(1., .50, .72), vec3(1., .72, .86), (q.y - 6.)/18.)*(.9 + .1*step(0., q.x));
            if(q.y < 8. && (q.y >= 7. || mod(floor(q.x), 2.) < 1.)) r = vec3(1., .95, .95);
            c = vec4(r, 1.);
        }
    }
    if(boite(q, -4., 24., 4., 30.)) c = vec4(1., .62, .78, 1.);
    if(boite(q, -4., 24., 4., 25.)) c = vec4(.98, .78, .28, 1.);
    if(length(q - vec2(-7., 28.5)) < 2.6 || length(q - vec2(7., 28.5)) < 2.6) c = vec4(1., .96, .96, 1.);

    if(salut < .5){
        if(boite(q, -6., 22., -4., 26.) || boite(q, 4., 22., 6., 26.)) c = vec4(peau, 1.);
    } else {
        if(boite(q, -9., 21., -7., 27.)) c = vec4(peau, 1.);
        if(distSegment(q, vec2(7., 28.), vec2(13., 40.)) < 1.1) c = vec4(peau, 1.);
        if(length(q - vec2(13., 41.)) < 1.8) c = vec4(peau, 1.);
    }

    float m = marche*2. - 1.;
    if(boite(q, -4. + m, 3., -2. + m, 5.) || boite(q, 2. - m, 3., 4. - m, 5.)) c = vec4(1., .45, .65, 1.);

    vec2 th = q - vec2(0., 35.5);
    if(dot(th, th) < 30.) c = vec4(peau, 1.);
    if(dot(th, th) < 30. && q.y >= 38.) c = vec4(blond, 1.);
    if(boite(q, -6., 33., -5., 40.) || boite(q, 5., 33., 6., 40.)) c = vec4(blond, 1.);
    if(boite(q, -3., 35., -2., 36.) || boite(q, 2., 35., 3., 36.)) c = vec4(.12, .07, .20, 1.);
    if(boite(q, -4., 33., -3., 33.) || boite(q, 3., 33., 4., 33.)) c = vec4(1., .60, .65, 1.);
    if(boite(q, -1., 32., 1., 32.)) c = vec4(.80, .25, .35, 1.);

    if(boite(q, -4., 41., 4., 42.)) c = vec4(.98, .80, .20, 1.);
    if(boite(q, -4., 43., -4., 44.) || boite(q, 4., 43., 4., 44.) || boite(q, -2., 43., -2., 45.) || boite(q, 2., 43., 2., 45.) || boite(q, 0., 43., 0., 46.)) c = vec4(.98, .80, .20, 1.);
    if(boite(q, 0., 41., 0., 42.)) c = vec4(1., .15, .25, 1.);
    return c;
}

vec4 iconeObjet(vec2 q, int numero)
{
    if(q.x < 0. || q.x > 15. || q.y < 0. || q.y > 15.) return vec4(0.);
    if(numero == 0){
        vec2 cq = (q - vec2(8., 9.))/vec2(7., 5.);
        if(dot(cq, cq) < 1. && q.y >= 7.){
            vec3 c = vec3(1., .45, .60);
            if(length(q - vec2(5., 10.)) < 1.6 || length(q - vec2(11., 10.5)) < 1.5 || length(q - vec2(8., 12.5)) < 1.1) c = vec3(1.);
            return vec4(c, 1.);
        }
        if(boite(q, 5., 3., 11., 6.)) return vec4(.99, .93, .85, 1.);
    } else if(numero == 1){
        vec2 d = q - 7.5;
        float rayon = length(d);
        if(rayon < 7.*(.58 + .42*cos(atan(d.y, d.x)*5. + 1.57))) return vec4(1., .88, .30, 1.);
    } else if(numero == 2){
        if(dansCoeur(q - vec2(7.5, 7.), 5.5)){
            vec3 c = vec3(1., .40, .62);
            if(length(q - vec2(5., 10.)) < 1.4) c = vec3(1.);
            return vec4(c, 1.);
        }
    }
    return vec4(0.);
}

void poser(inout vec3 couleur, inout float tamponZ, vec4 c, float zRelatif, float profObjet, vec2 p)
{
    if(c.a > .5 && zRelatif < tamponZ){
        tamponZ = zRelatif;
        couleur = mix(c.rgb, BRUME, tramage(facteurBrume(profObjet), p));
    }
}

void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    float echelleEcran = min(iResolution.x/RESOLUTION.x, iResolution.y/RESOLUTION.y);
    vec2 pixelBrut = floor((fragCoord - .5*iResolution.xy)/echelleEcran + RESOLUTION*.5);

    float temps = mod(iTime, DUREE);
    float course = max(temps - DEPART, 0.);
    float apresArrivee = temps - ARRIVEE;
    float trajet = trajetTemps(temps);
    float posHeros = lateralHeros(trajet);
    float centreX = RESOLUTION.x*.5;
    float baseCourbe = courbe(trajet);
    float pente = courbe(trajet + .5) - courbe(trajet - .5);

    float collision = 0.;
    float tempsCollision = 0.;
    for(int j = 0; j < 3; j++){
        float indice = floor((trajet - .8)/PAS) - float(j);
        float zObjet = indice*PAS;
        float tempsEcoule = (trajet - (zObjet - .8))/VITESSE;
        if(tempsEcoule >= 0. && tempsEcoule < .5 && hasard1(indice*7.13) > .78 && zObjet < LIGNE - 12.){
            if(abs(lateralSlime(indice, iTime - tempsEcoule) - lateralHeros(zObjet - .8)) < .3){
                float h = 1. - tempsEcoule/.5;
                if(h > collision){ collision = h; tempsCollision = tempsEcoule; }
            }
        }
    }
    vec2 secousse = vec2(floor(sin(iTime*90.)*collision*2. + .5), floor(cos(iTime*77.)*collision*2. + .5));
    vec2 p = pixelBrut + secousse;

    float phase = mod(trajet, 120.);
    float impulsion = (phase > 119.) ? 1. : ((phase < 17.2) ? 1. : max(0., .6*(1. - (phase - 17.2)/24.)));
    impulsion *= (1. - step(LIGNE - 40., trajet))*step(.001, trajet);

    int numeroIcone = -1;
    float recul = 0.;
    for(int r = 0; r < 3; r++){
        float lancer = profilRival(r).y - 5.5;
        if(course > lancer - 3. && course <= lancer - 1.) numeroIcone = int(mod(floor(iTime*9.), 3.));
        if(course > lancer - 1. && course <= lancer) numeroIcone = (r == 1) ? 1 : 2;
        recul += step(lancer, course)*step(course, lancer + .18)*3.;
    }

    float fete = step(6.2, apresArrivee)*step(apresArrivee, DUREE - ARRIVEE);
    float sautFete = floor(abs(sin((apresArrivee - 6.2)*5.))*4.)*fete;
    float inclinaison = clamp((lateralHeros(trajet + 2.) - lateralHeros(trajet))*14. + ecartRoute(trajet + 10., trajet, baseCourbe, pente)*.25, -1.2, 1.2);
    float rebond = floor(sin(trajet*5.)*.5 + .5);
    float saut = floor(sin(3.14159*clamp(tempsCollision/.5, 0., 1.))*8.*step(.001, collision)) + recul + sautFete;
    vec2 pixelEntier = floor(p);

    vec3 couleur;
    float tamponZ = 1e9;

    if(p.y >= HORIZON){
        float t = (p.y - HORIZON)/(RESOLUTION.y - HORIZON);
        vec3 teinte0 = vec3(1., .88, .90), teinte1 = vec3(.98, .74, .90), teinte2 = vec3(.68, .66, .96), teinte3 = vec3(.50, .56, .94);
        float niveauCiel = clamp(floor(t*9. + seuilBayer(p))/9., 0., 1.);
        couleur = niveauCiel < .3 ? mix(teinte0, teinte1, niveauCiel/.3) : (niveauCiel < .65 ? mix(teinte1, teinte2, (niveauCiel - .3)/.35) : mix(teinte2, teinte3, (niveauCiel - .65)/.35));

        if(p.y > HORIZON + 24. && hasard2(p) > .992) couleur = vec3(1., .96, .85)*(.7 + .3*sin(iTime*3. + hasard2(p + 7.)*20.));

        vec2 versArc = p - vec2(centreX - pente*40., HORIZON - 25.);
        float rayonArc = length(versArc);
        if(rayonArc > 34. && rayonArc < 52.){
            int bandeArc = 5 - int((rayonArc - 34.)/3.);
            vec3 teinteArc = (bandeArc == 0) ? vec3(1., .55, .60) : ((bandeArc == 1) ? vec3(1., .75, .55) : ((bandeArc == 2) ? vec3(1., .95, .60) : ((bandeArc == 3) ? vec3(.65, .95, .70) : ((bandeArc == 4) ? vec3(.60, .82, 1.) : vec3(.80, .70, 1.)))));
            couleur = mix(couleur, teinteArc, .75);
        }

        for(int n = 0; n < 5; n++){
            float numNuage = float(n);
            float xNuage = RESOLUTION.x + 40. - mod(iTime*(1.5 + numNuage*.4) + numNuage*67., RESOLUTION.x + 80.) - pente*(8. + numNuage*3.);
            float yNuage = HORIZON + 22. + numNuage*5. + 2.*sin(iTime*.3 + numNuage);
            float taille = 1. + .25*numNuage;
            vec2 dn = p - vec2(xNuage, yNuage);
            bool nuage = length(dn) < 5.*taille || length(dn - vec2(-6.*taille, -1.)) < 3.8*taille || length(dn - vec2(6.*taille, -1.)) < 4.2*taille || length(dn - vec2(-2.5*taille, 2.5*taille)) < 4.*taille;
            if(nuage && dn.y > -3.*taille) couleur = mix(vec3(1., .97, .98), vec3(.98, .86, .94), clamp(.4 - dn.y*.08, 0., 1.));
        }

        float xDragon = mod(iTime*13., 280.) - 50.;
        vec2 qDragon = floor((p + .5 - vec2(xDragon, 96. + 3.*sin(iTime*.9)))/1.5);
        vec4 dragon = spriteDragon(qDragon, iTime);

        float xMont1 = p.x + pente*18.;
        float hauteurMont1 = 11. + 7.*sin(xMont1*.03 + 1.) + 4.*sin(xMont1*.09 + 2.);
        if(p.y < HORIZON + hauteurMont1){
            couleur = mix(vec3(.80, .72, .96), vec3(.90, .80, 1.), (p.y - HORIZON)/hauteurMont1);
            if(p.y > HORIZON + hauteurMont1 - 1.) couleur = vec3(1., .92, 1.);
        }
        float xMont2 = p.x + pente*36.;
        float hauteurMont2 = 6. + 5.*sin(xMont2*.05) + 3.*sin(xMont2*.14 + 1.);
        if(p.y < HORIZON + hauteurMont2){
            couleur = mix(vec3(.62, .90, .78), vec3(.76, .97, .84), (p.y - HORIZON)/hauteurMont2);
            if(p.y > HORIZON + hauteurMont2 - 1.) couleur = vec3(.90, 1., .92);
        }
        if(dragon.a > .5 && p.y > HORIZON + 3.) couleur = dragon.rgb;

        for(int b = 0; b < 4; b++){
            float numChauve = float(b);
            float xChauve = RESOLUTION.x + 20. - mod(iTime*(10. + numChauve*3.) + numChauve*53., RESOLUTION.x + 40.);
            float yChauve = 90. + 7.*sin(iTime*1.4 + numChauve*2.) + numChauve*2.;
            float echelleChauve = 2. + step(1.5, numChauve);
            vec2 qChauve = floor((p + .5 - vec2(xChauve, yChauve))/echelleChauve);
            if(abs(qChauve.x) <= 8. && qChauve.y >= -3. && qChauve.y <= 6.){
                float battement = sin(iTime*10. + numChauve*3.);
                float yAile = floor(1. + battement*(abs(qChauve.x) - 1.)*.55);
                bool aile = abs(qChauve.x) >= 2. && abs(qChauve.x) <= 7. && (qChauve.y == yAile || qChauve.y == yAile + 1.);
                bool corps = abs(qChauve.x) <= 1. && qChauve.y >= 0. && qChauve.y <= 2.;
                bool oreille = abs(qChauve.x) == 1. && qChauve.y == 3.;
                if(aile) couleur = vec3(.92, .72, 1.);
                if(corps || oreille) couleur = vec3(.70, .55, .92);
                if(abs(qChauve.x) == 1. && qChauve.y == 1.) couleur = vec3(.15, .08, .25);
                if(abs(qChauve.x) == 1. && qChauve.y == 0.) couleur = vec3(1., .62, .75);
            }
        }
    } else {
        float d  = HORIZON - p.y;
        float zCamera = 44./d;
        float zPixel = zCamera + trajet;
        float decalageCourbe = ecartRoute(zPixel, trajet, baseCourbe, pente);
        float decalage = posHeros + (p.x - centreX)/(d*LARGEUR) - decalageCourbe;
        float ecartAbs = abs(decalage);

        float bande = mod(floor(zPixel*.45), 2.);
        vec2 cellule = floor(vec2(decalage*7., zPixel*1.6));
        couleur = mix(vec3(.62, .90, .72), vec3(.70, .95, .78), bande);
        couleur *= .94 + .12*hasard2(floor(vec2(decalage*30., zPixel*6.)));
        couleur *= mix(1., .88, smoothstep(1.2, 4., ecartAbs));
        float aleaFleur = hasard2(cellule + 17.);
        if(ecartAbs > 1.3 && aleaFleur > .84){
            vec2 qFleur = fract(vec2(decalage*7., zPixel*1.6));
            if(length(qFleur - .5) < .18) couleur = (hasard2(cellule) < .33) ? vec3(1., .96, .55) : ((hasard2(cellule) < .66) ? vec3(1., .65, .82) : vec3(1.));
        }

        if(ecartAbs < 1.){
            float grain = hasard2(floor(vec2(decalage*26., zPixel*5.)));
            couleur = vec3(.80, .76, .90)*(.94 + .1*grain);
            couleur *= .94 + .06*mod(floor(zPixel*.9), 2.);
            couleur *= 1. - .1*(1. - smoothstep(0., .07, abs(ecartAbs - .3)));
            if(ecartAbs > .8 && ecartAbs < .85) couleur = vec3(1., .98, 1.);
            if(ecartAbs < .025 && mod(zPixel, 3.) < 1.6) couleur = vec3(1., .86, .93);
            if(ecartAbs > .87) couleur = (mod(floor(zPixel*.55), 2.) < .5) ? vec3(1., .55, .72) : vec3(1.);
            if(mod(zPixel, 120.) < 18. && ecartAbs < .72){
                couleur = vec3(.55, .70, 1.);
                float chevron = fract(zPixel*.32 - ecartAbs*1.5 - iTime*2.);
                if(chevron < .3) couleur = mix(vec3(.75, 1., 1.), vec3(1.), step(.2, chevron));
                if(ecartAbs > .68) couleur = vec3(1., .75, .92);
            }
            if((abs(zPixel - 4.) < 1. || abs(zPixel - LIGNE) < 1.) && ecartAbs < .86)
                couleur = (mod(floor(decalage*6.) + floor(zPixel*3.), 2.) < .5) ? vec3(1.) : vec3(.45, .35, .65);
            if(zPixel > LIGNE + 6. && zPixel < LIGNE + 70. && ecartAbs < .6){
                couleur = vec3(1., .50, .68)*(.9 + .1*mod(floor(zPixel*.8), 2.));
                if(ecartAbs > .54) couleur = vec3(.98, .80, .22);
            }
        }

        couleur = mix(couleur, BRUME, tramage(facteurBrume(d), p));
    }

    for(int i = 0; i < 14; i++){
        float indice = floor(trajet/PAS) + float(i);
        float zObjet = indice*PAS;
        float zRelatif = zObjet - trajet;
        if(zRelatif < .6) continue;
        float profObjet = 44./zRelatif;
        if(profObjet > 70. || profObjet < 1.5) continue;
        float echelle0 = profObjet/56.;
        float ySol = floor(HORIZON - profObjet + .5);
        float decalageCourbeObjet = ecartRoute(zObjet, trajet, baseCourbe, pente);

        for(int indiceCote = 0; indiceCote < 4; indiceCote++){
            float cote = (indiceCote % 2 == 0) ? -1. : 1.;
            float rangee = float(indiceCote/2);
            float h = hasard1(indice*3.1 + float(indiceCote)*7.7);
            if(rangee > .5 && h < .35) continue;
            float couloir = cote*(1.55 + rangee*1.3 + .6*h);
            float echelle = echelle0*(1.5 + .5*h);
            float xEcran = centreX + (couloir + decalageCourbeObjet - posHeros)*profObjet*LARGEUR;
            vec2 q = floor((p + .5 - vec2(floor(xEcran), ySol))/echelle);
            poser(couleur, tamponZ, spriteArbre(q, h), zRelatif, profObjet, p);
        }

        if(mod(indice, 4.) < .5){
            for(int indiceCote = 0; indiceCote < 2; indiceCote++){
                float cote = (indiceCote == 0) ? -1. : 1.;
                float xEcran = centreX + (cote*1.22 + decalageCourbeObjet - posHeros)*profObjet*LARGEUR;
                vec2 q = floor((p + .5 - vec2(floor(xEcran), ySol))/(echelle0*1.5));
                poser(couleur, tamponZ, spriteLampadaire(q, iTime), zRelatif, profObjet, p);
            }
        }

        if(mod(indice, 9.) < .5 && zObjet < LIGNE - 12.){
            for(int j = -1; j <= 1; j++){
                float xEcran = centreX + (float(j)*.5 + decalageCourbeObjet - posHeros)*profObjet*LARGEUR;
                float echelle = echelle0*1.3;
                vec2 q = floor((p + .5 - vec2(floor(xEcran), ySol))/echelle);
                q.y = floor(q.y - (5. + 2.*sin(iTime*3. + indice + float(j))));
                poser(couleur, tamponZ, spriteBoite(q, iTime), zRelatif, profObjet, p);
            }
        }

        if(hasard1(indice*7.13) > .78 && zObjet < LIGNE - 12.){
            bool ecrase = false;
            if(zRelatif < .85){
                float tempsEcoule = (trajet - (zObjet - .8))/VITESSE;
                ecrase = abs(lateralSlime(indice, iTime - tempsEcoule) - lateralHeros(zObjet - .8)) < .3;
            }
            if(!ecrase){
                float lateral = lateralSlime(indice, iTime);
                float xEcran = centreX + (lateral + decalageCourbeObjet - posHeros)*profObjet*LARGEUR;
                float echelle = echelle0*1.5;
                vec2 q = floor((p + .5 - vec2(floor(xEcran), ySol))/echelle);
                float sautSlime = floor(6.*abs(sin(iTime*3.5 + indice*1.7)));
                float variante = step(.5, hasard1(indice*2.9));
                poser(couleur, tamponZ, spriteSlime(q, sautSlime, variante, iTime), zRelatif, profObjet, p);
            }
        }
    }

    float zRelatifArche = LIGNE - trajet;
    if(zRelatifArche > .6 && zRelatifArche < 40.){
        float profArche = 44./zRelatifArche;
        float ySolArche = floor(HORIZON - profArche + .5);
        float decalageArche = ecartRoute(LIGNE, trajet, baseCourbe, pente);
        float unite = profArche*LARGEUR;
        float xGauche = centreX + (-1.15 + decalageArche - posHeros)*unite;
        float xDroite = centreX + (1.15 + decalageArche - posHeros)*unite;
        float hauteur = 1.3*unite;
        float epaisseur = max(1., .07*unite);
        float hautPixel = p.y - ySolArche;
        bool dansArche = false;
        vec3 teinteArche = vec3(0.);
        if((abs(p.x - xGauche) <= epaisseur || abs(p.x - xDroite) <= epaisseur) && hautPixel >= 0. && hautPixel <= hauteur){
            dansArche = true;
            teinteArche = (mod(floor(hautPixel/(.15*unite) + 1.), 2.) < .5) ? vec3(1., .55, .72) : vec3(1.);
        }
        if(p.x >= xGauche - epaisseur && p.x <= xDroite + epaisseur && hautPixel >= hauteur - .35*unite && hautPixel <= hauteur){
            dansArche = true;
            float carreau = .12*unite;
            teinteArche = (mod(floor((p.x - xGauche)/carreau) + floor(hautPixel/carreau), 2.) < .5) ? vec3(1.) : vec3(.45, .35, .65);
        }
        if(dansArche) poser(couleur, tamponZ, vec4(teinteArche, 1.), zRelatifArche, profArche, p);
    }

    bool coupeVisible = false;
    vec2 positionCoupe = vec2(0.);
    float echelleCoupe = 1.;
    float envol = 0.;
    if(apresArrivee > 1.5){
        float marche = step(.5, fract(apresArrivee*3.))*step(apresArrivee, 4.5);
        float latPrincesse = posHeros + mix(3.6, .95, smoothstep(1.5, 4.5, apresArrivee));
        float zPrincesse = 1.3;
        float profPrincesse = 44./zPrincesse;
        float echellePrincesse = profPrincesse/56.*1.5;
        float xPrincesse = centreX + (latPrincesse + ecartRoute(trajet + zPrincesse, trajet, baseCourbe, pente) - posHeros)*profPrincesse*LARGEUR;
        float ySolPrincesse = floor(HORIZON - profPrincesse + .5);
        vec2 qPrincesse = floor((p + .5 - vec2(floor(xPrincesse), ySolPrincesse))/echellePrincesse);
        float salut = step(6.2, apresArrivee);
        poser(couleur, tamponZ, spritePrincesse(qPrincesse, marche, salut), zPrincesse, profPrincesse, p);

        vec2 mainPrincesse = vec2(floor(xPrincesse), ySolPrincesse + 19.*echellePrincesse);
        vec2 mainHeros = vec2(centreX, 52. + floor(2.*sin(apresArrivee*6.)) + sautFete);
        envol = smoothstep(5.2, 6.2, apresArrivee);
        positionCoupe = mix(mainPrincesse, mainHeros, envol) + vec2(0., 14.*sin(3.14159*envol));
        echelleCoupe = mix(echellePrincesse*.65, 1., envol);
        coupeVisible = true;
    }

    vec4 procheRival = vec4(0.);
    float zProche = 1e9;
    float regard = 0.;
    int depasses = 0;
    for(int r = 0; r < 3; r++){
        vec4 profil = profilRival(r);
        float zRelatif = zRelatifRival(r, course);
        float lateral = lateralRival(r, course, zRelatif, posHeros);
        float frappe = profil.y - 4.5;
        float lancer = frappe - 1.;
        float ageCoup = course - frappe;
        if(zRelatif < .8) depasses++;
        regard += profil.z*(1. - smoothstep(1.6, 2.8, zRelatif))*smoothstep(.5, .9, zRelatif);

        if(zRelatif > .5 && zRelatif < 40.){
            float decalageObjet = ecartRoute(trajet + zRelatif, trajet, baseCourbe, pente);
            float profObjet = 44./zRelatif;
            float echelle = profObjet/56.;
            float xEcran = centreX + (lateral + decalageObjet - posHeros)*profObjet*LARGEUR;
            float ySol = floor(HORIZON - profObjet + .5);
            vec2 q = floor((p + .5 - vec2(floor(xEcran), ySol))/echelle);
            if(ageCoup > 0. && ageCoup < 1.3){
                float rotationCoup = cos(ageCoup*14.);
                float facteur = (rotationCoup >= 0.) ? max(rotationCoup, .15) : min(rotationCoup, -.15);
                q.x = floor(q.x/facteur);
                q.y = floor(q.y - 7.*sin(3.14159*ageCoup/1.3));
            }
            vec3 couleurCarrosserie = (r == 0) ? vec3(.55, .90, .65) : ((r == 1) ? vec3(.75, .65, .98) : vec3(1., .72, .50));
            float inclinaisonRival = .5*cos(iTime*.55 + profil.w*2.4);
            vec4 spr = kartDeDos(q, r + 1, couleurCarrosserie, iTime, inclinaisonRival, trajet*1.5, 0., 0.);
            if(zRelatif >= .79){
                poser(couleur, tamponZ, spr, zRelatif, profObjet, p);
            } else if(spr.a > .5 && zRelatif < zProche){
                zProche = zRelatif;
                procheRival = vec4(mix(spr.rgb, BRUME, tramage(facteurBrume(profObjet), p)), 1.);
            }

            if(ageCoup >= 0. && ageCoup < .45){
                vec2 versCentre = p + .5 - vec2(floor(xEcran), ySol + 16.*echelle);
                float rayon = length(versCentre);
                float angle = atan(versCentre.y, versCentre.x);
                float ampleur = (5. + 38.*ageCoup/.45)*echelle*((r == 1) ? 1.5 : 1.);
                float forme = ampleur*(.62 + .38*cos(angle*6.));
                if(rayon < forme){
                    vec3 feu = mix(vec3(1., .98, .70), vec3(1., .55, .80), rayon/forme);
                    poser(couleur, tamponZ, vec4(feu, 1.), zRelatif - .05, profObjet, p);
                }
            }

            if(course > lancer && course < frappe){
                float avancement = (course - lancer)/(frappe - lancer);
                float zProjectile = mix(.95, zRelatif, avancement);
                float latProjectile = mix(posHeros, lateral, avancement);
                float arc = 5. + 9.*sin(3.14159*avancement);
                float profProjectile = 44./zProjectile;
                float echelleProjectile = profProjectile/56.*1.4;
                float xProjectile = centreX + (latProjectile + ecartRoute(trajet + zProjectile, trajet, baseCourbe, pente) - posHeros)*profProjectile*LARGEUR;
                float ySolProjectile = floor(HORIZON - profProjectile + .5);
                vec2 qProjectile = floor((p + .5 - vec2(floor(xProjectile), ySolProjectile + floor(arc*echelleProjectile)))/echelleProjectile);
                poser(couleur, tamponZ, spriteProjectile(qProjectile, (r == 1) ? 1. : 0., iTime), zProjectile, profProjectile, p);
            }
        }
    }
    regard = clamp(regard, -1., 1.);

    vec2 repereOmbre = pixelEntier - vec2(centreX, 7. + rebond);
    vec2 formeOmbre = repereOmbre/vec2(19., 3.);
    if(dot(formeOmbre, formeOmbre) < 1.) couleur *= .5;

    vec2 repereKart = pixelEntier - vec2(centreX, 6. + rebond + saut);
    vec4 pixelKart = kartDeDos(repereKart, 0, vec3(1., .55, .72), iTime, inclinaison, trajet*1.5, impulsion, regard);
    if(pixelKart.a > .5) couleur = pixelKart.rgb;
    if(procheRival.a > .5) couleur = procheRival.rgb;

    if(collision > 0.){
        for(int i = 0; i < 4; i++){
            float a = iTime*12. + float(i)*1.5708;
            vec2 etoile = vec2(centreX, 6. + saut + 44.) + vec2(cos(a)*14., sin(a)*4.);
            if(dansCoeur(pixelEntier - floor(etoile), 2.4)) couleur = vec3(1., .50, .70);
        }
    }

    if(apresArrivee < 0. && trajet > .001){
        for(int i = 0; i < 3; i++){
            float k = fract(iTime*.9 + float(i)*.34);
            vec2 coeurFlottant = vec2(centreX + (float(i) - 1.)*14. + 4.*sin(iTime*3. + float(i)*2.), 48. + k*30.);
            if(k < .85 && dansCoeur(pixelEntier - floor(coeurFlottant), 1.6 + .8*(1. - k))) couleur = vec3(1., .62, .78);
        }
    }

    if(coupeVisible){
        vec2 qCoupe = floor((p + .5 - positionCoupe)/echelleCoupe);
        vec4 coupe = spriteCoupe(qCoupe, iTime);
        if(coupe.a > .5) couleur = coupe.rgb;
        if(envol > .99){
            for(int i = 0; i < 6; i++){
                float a = iTime*3. + float(i)*1.047;
                float rayonEtincelle = 12. + 4.*sin(iTime*5. + float(i));
                vec2 etincelle = positionCoupe + vec2(0., 8.) + vec2(cos(a), sin(a))*rayonEtincelle;
                vec2 ecartEtincelle = abs(pixelEntier - floor(etincelle));
                if(ecartEtincelle.x + ecartEtincelle.y <= 1. && sin(iTime*9. + float(i)*2.) > 0.) couleur = vec3(1., .98, .75);
            }
        }
    }

    if(impulsion > 0.){
        vec2 versFuite = pixelBrut - vec2(centreX, HORIZON);
        float angleLigne = atan(versFuite.y, versFuite.x);
        float rayonLigne = length(versFuite);
        float numLigne = floor(angleLigne*30.);
        float h = hasard1(numLigne);
        float traine = fract(rayonLigne*.02 - iTime*5.*(.6 + h) + h*10.);
        if(h > .6 && traine < .18 && rayonLigne > 40.) couleur = mix(couleur, vec3(.8, .95, 1.), impulsion*.55);
    }

    if(apresArrivee > 5.5 && apresArrivee < DUREE - ARRIVEE){
        for(int k = 0; k < 2; k++){
            float couche = float(k);
            vec2 chute = vec2(pixelBrut.x + 6.*sin(iTime*2. + couche*3. + pixelBrut.y*.05), pixelBrut.y + iTime*(30. + couche*17.));
            vec2 celluleConfetti = floor(chute/vec2(5., 7.));
            float h = hasard2(celluleConfetti + couche*13.);
            if(h > .88){
                vec2 local = mod(chute, vec2(5., 7.));
                if((h > .95) ? dansCoeur(local - vec2(2.5, 3.5), 2.2) : (local.x < 2. && local.y < 2.)) couleur = .55 + .45*cos(h*40. + vec3(0., 2., 4.));
            }
        }
    }

    vec2 uv = pixelBrut/RESOLUTION - .5;
    float vignette = 1. - .20*dot(uv, uv);
    couleur *= vignette;
    couleur = mix(couleur, vec3(1., .75, .85), collision*.30*smoothstep(.1, .5, dot(uv, uv)*2.));
    couleur = pow(max(couleur, 0.), vec3(.9));
    couleur *= .985 + .015*mod(pixelBrut.y, 2.);

    if(boite(pixelBrut, 6., 84., 25., 103.)){
        bool bord = pixelBrut.x < 7. || pixelBrut.x > 24. || pixelBrut.y < 85. || pixelBrut.y > 102.;
        couleur = bord ? vec3(1., .62, .80) : mix(couleur, vec3(1., .93, .96), .75);
        vec4 icone = iconeObjet(pixelBrut - vec2(8., 86.), numeroIcone);
        if(icone.a > .5) couleur = icone.rgb;
    }
    int classement = 4 - depasses;
    if(texteRang(pixelBrut - vec2(1., -1.), classement) > .5) couleur = vec3(.62, .28, .50);
    if(texteRang(pixelBrut, classement) > .5) couleur = vec3(1., .92, .55);

    if(apresArrivee > .4){
        vec2 origineVictoire = vec2(centreX - 46., 88.);
        if(texteVictoire(pixelBrut - vec2(1., -1.), origineVictoire, 3.) > .5) couleur = vec3(.62, .28, .50);
        if(texteVictoire(pixelBrut, origineVictoire, 3.) > .5) couleur = .5 + .5*cos(iTime*6. + vec3(0., 2., 4.));
    }

    if(comptage(pixelBrut - vec2(1., -1.), temps, centreX) > .5) couleur = vec3(.62, .28, .50);
    if(comptage(pixelBrut, temps, centreX) > .5) couleur = teinteComptage(temps);

    fragColor = vec4(couleur, 1.);
}

#define PI2 6.2831853
#define DEPART 3.
#define ARRIVEE 38.
#define DUREE 60.

const int MELODIE_COURSE[32] = int[32](7,-1,4,7,12,-1,7,4, 9,-1,12,9,4,-1,9,12, 5,-1,9,12,17,-1,12,9, 7,11,14,11,7,-1,2,-1);
const int MELODIE_VICTOIRE[32] = int[32](0,-1,0,4,7,-1,4,0, 5,-1,5,9,12,-1,9,5, 7,-1,7,11,14,-1,11,7, 12,-1,7,-1,12,-1,-1,-1);
const int RACINES_COURSE[4] = int[4](0,9,5,7);
const int RACINES_VICTOIRE[4] = int[4](0,5,7,0);
const int BASSE[8] = int[8](0,0,12,0,0,12,7,12);
const int PENTATONIQUE[5] = int[5](0,2,4,7,9);
const int HARPE[8] = int[8](0,4,7,12,16,19,24,28);
const float PASSE[3] = float[3](9., 17., 26.);
const float COTE[3] = float[3](-1., 1., -1.);

float graine;
float indexEchantillon;
float pompe;

float hasard(float x)
{
    return fract(sin(x*12.9898)*43758.5453);
}

float blanc()
{
    return hasard(graine)*2. - 1.;
}

float blancHaut()
{
    return blanc() - (hasard(graine - 1.)*2. - 1.);
}

float blancLisse(float x)
{
    float i = floor(x);
    float f = fract(x);
    f = f*f*(3. - 2.*f);
    return mix(hasard(i)*2. - 1., hasard(i + 1.)*2. - 1., f);
}

float freq(float n, float base)
{
    return base*exp2(n/12.);
}

float carre(float ph, float cycle)
{
    return (fract(ph) < cycle) ? 1. : -1.;
}

float triangle(float ph)
{
    return abs(fract(ph + .25) - .5)*4. - 1.;
}

float scie(float ph)
{
    return fract(ph)*2. - 1.;
}

float env(float tl, float attaque, float chute)
{
    if(tl < 0.) return 0.;
    return min(tl/attaque, 1.)*exp(-tl/chute);
}

vec2 place(float x, float p)
{
    return x*vec2(1. - max(p, 0.), 1. + min(p, 0.));
}

float cloche(float tl, float f, float duree)
{
    if(tl < 0.) return 0.;
    return (sin(PI2*f*tl) + .3*sin(PI2*2.*f*tl)*exp(-tl/(duree*.5)))*env(tl, .001, duree);
}

vec2 couches(float mt, bool victoire, float batterie, float melodie)
{
    int mesure = int(floor(mt/2.));
    int accord = mesure - (mesure/4)*4;
    int racine = victoire ? RACINES_VICTOIRE[accord] : RACINES_COURSE[accord];
    float tierce = (!victoire && accord == 1) ? 3. : 4.;
    float r = float(racine);
    vec2 s = vec2(0.);

    float pas16 = floor(mt/.125);
    float tl16 = mod(mt, .125);
    int k = int(mod(pas16, 4.));
    float ton = (k == 0) ? 0. : ((k == 1) ? tierce : ((k == 2) ? 7. : 12.));
    float fa = freq(r + ton, 261.63);
    float rebond = .55 + .45*smoothstep(0., .22, mod(mt, .5));
    float arpege = carre(fa*tl16, .25)*env(tl16, .002, .11)*.07*rebond;
    s += place(arpege, (mod(pas16, 2.) < 1.) ? -.45 : .45);

    float pas8 = floor(mt/.25);
    float tl8 = mod(mt, .25);
    int kb = int(mod(pas8, 8.));
    float fb = freq(r + float(BASSE[kb]), 65.406);
    s += place(triangle(fb*tl8)*env(tl8, .004, .17)*.26, 0.);

    int idx = int(mod(pas8, 32.));
    int n = victoire ? MELODIE_VICTOIRE[idx] : MELODIE_COURSE[idx];
    if(n >= 0){
        float fl = freq(float(n), 523.25);
        float vibrato = .35*sin(PI2*6.*tl8)*smoothstep(.05, .2, tl8);
        float lead = (carre(fl*tl8 + vibrato*.01, .5)*.45 + sin(PI2*fl*tl8 + vibrato)*.55)*env(tl8, .003, .22)*.10*melodie;
        s += place(lead, .2) + place(lead*.35, -.3)*step(.5, melodie);
    }

    float tb = mod(mt, .5);
    float kick = sin(PI2*(52.*tb + 3.75*(1. - exp(-tb*40.))))*env(tb, .001, .11)*.5;
    float temps = floor(mt/.5);
    float caisse = 0.;
    if(mod(temps, 2.) > .5) caisse = (blanc()*.6 + sin(PI2*185.*tb)*.4)*env(tb, .001, .07)*.32;
    float charley = blancHaut()*env(tl8, .001, .018)*((mod(pas8, 2.) > .5) ? .16 : .09);
    s += place(kick + caisse, 0.)*batterie + place(charley, .5)*batterie;
    return s;
}

vec2 moteur(float t)
{
    float a = clamp(t - DEPART, 0., 1.2);
    float c = clamp(t - DEPART - 1.2, 0., ARRIVEE - DEPART - 1.2);
    float u = clamp((t - ARRIVEE)/2.5, 0., 1.);
    float v = (t < DEPART) ? 0. : ((t < DEPART + 1.2) ? (t - DEPART)/1.2 : ((t < ARRIVEE) ? 1. : 1. - u));
    float integrale = a*a/2.4 + c + 2.5*(u - u*u*.5);
    float phase = 38.*t + 52.*integrale;
    float onde = scie(phase)*.45 + carre(phase*2., .3)*.2 + triangle(phase*.5)*.4 + blancLisse(t*2600.)*.18*v;
    float volume = (.03 + .06*v)*(1. - smoothstep(ARRIVEE + 2.2, ARRIVEE + 2.5, t));
    float vent = blancLisse(indexEchantillon*.05)*.06*v*v*(1. - smoothstep(ARRIVEE + 1.5, ARRIVEE + 3., t));
    return vec2(onde*volume + vent);
}

vec2 musique(float t)
{
    if(t < DEPART) return vec2(0.);
    if(t < ARRIVEE){
        float mt = t - DEPART;
        return couches(mt, false, 1., step(4., mt))*(1. - smoothstep(ARRIVEE - .15, ARRIVEE, t));
    }
    if(t >= ARRIVEE + 2.){
        float mv = t - (ARRIVEE + 2.);
        return couches(mv, true, step(4., mv), 1.)*(1. - smoothstep(DUREE - 1.5, DUREE, t));
    }
    return vec2(0.);
}

vec2 effets(float t)
{
    vec2 s = vec2(0.);

    for(int i = 0; i < 3; i++){
        float tl = t - float(i);
        s += place(sin(PI2*392.*tl)*.6 + triangle(392.*tl)*.4, 0.)*env(tl, .003, .13)*.3;
    }

    float tg = t - DEPART;
    s += place((sin(PI2*784.*tg)*.5 + carre(784.*tg, .5)*.15 + sin(PI2*1176.*tg)*.25)*env(tg, .003, .4)*.3 + blancHaut()*env(tg, .12, .35)*.06, 0.);

    for(int i = 0; i < 3; i++){
        float passe = DEPART + PASSE[i];
        float frappe = passe - 4.5;
        float lancer = frappe - 1.;
        float cote = COTE[i];
        bool bombe = (i == 1);
        float gros = bombe ? 1.4 : 1.;

        float tl = t - lancer;
        float pew = sin(PI2*(600.*tl + 1000.*tl*tl))*env(tl, .002, .09)*.22;
        float chant = sin(PI2*330.*tl + 4.*sin(PI2*9.*tl))*.05*smoothstep(0., .1, tl)*(1. - smoothstep(.6, 1., tl))*step(tl, 1.)*step(0., tl);
        s += place(pew + chant, cote*.4);

        float th = t - frappe;
        float thp = max(th, 0.);
        float boum = sin(PI2*(38.*thp + 7.*(1. - exp(-thp*12.))))*env(th, .002, .45)*.55*gros;
        float craquement = blanc()*env(th, .001, .07)*.3*gros;
        float sourd = blancLisse(indexEchantillon*.08)*env(th, .002, .5)*.45*gros;
        float boing = sin(PI2*(250.*thp + 94.*(1. - exp(-thp*9.))))*env(th, .002, .25)*.22*step(th, .9);
        float toupie = sin(PI2*520.*th + 14.*sin(PI2*6.5*th))*.07*(1. - smoothstep(.9, 1.5, th))*smoothstep(.1, .25, th)*step(th, 1.5);
        float etincelles = cloche(th - .05, 2093., .12)*.08 + cloche(th - .14, 2637., .12)*.07;
        s += place(boum + craquement + sourd + boing + toupie + etincelles, cote*.5);
        if(th > 0.) pompe = min(pompe, 1. - .6*exp(-th*3.5));

        float tp = t - passe;
        float gauss = exp(-min(tp*tp*6., 80.));
        float souffle = blancLisse(indexEchantillon*mix(.6, .12, smoothstep(-.4, .5, tp)))*gauss*.24;
        float ding = (cloche(tp, 1568., .18) + cloche(tp - .12, 2093., .22))*.1*step(0., tp);
        s += place(souffle, cote*.7) + place(ding, cote*.3);
    }

    for(int k = 0; k < 4; k++){
        float tp = t - (3.6 + 7.5*float(k + 1));
        float fenetre = smoothstep(0., .03, tp)*(1. - smoothstep(.6, 1.1, tp));
        float balayage = scie(300.*tp + 1400.*tp*tp)*.1*fenetre;
        float swish = blancLisse(indexEchantillon*.3)*smoothstep(0., .1, tp)*exp(-max(tp, 0.)*4.)*.22*step(0., tp);
        float notes = cloche(tp, 1046.5, .09)*.08 + cloche(tp - .08, 1318.5, .09)*.08 + cloche(tp - .16, 1568., .16)*.1;
        s += place(balayage + swish + notes, 0.);
    }

    float tf = t - ARRIVEE;
    s += place(blancHaut()*env(tf, .002, .9)*.22, 0.);
    for(int i = 0; i < 3; i++){
        float tn = tf - .2*float(i);
        float f = (i == 0) ? 523.25 : ((i == 1) ? 659.25 : 783.99);
        float duree = .12;
        float cuivre = (carre(f*tn + .004*sin(PI2*6.*tn), .35)*.5 + scie(f*tn)*.3)*env(tn, .01, duree)*.12;
        s += place(cuivre, 0.);
    }
    float tn = tf - .6;
    float vib = .004*sin(PI2*6.*tn)*smoothstep(.1, .5, tn);
    float accordFinal = 0.;
    accordFinal += carre(523.25*2.*tn + vib, .35)*.5 + scie(523.25*2.*tn)*.3;
    accordFinal += carre(659.25*tn + vib, .35)*.4;
    accordFinal += carre(783.99*tn + vib, .35)*.4;
    s += place(accordFinal*env(tn, .01, 1.1)*.07, 0.);
    float foule = (blancLisse(indexEchantillon*.12) + .6*blancLisse(indexEchantillon*.05))*(1. + .5*sin(tf*9.))*smoothstep(0., .4, tf)*(1. - smoothstep(3., 6., tf))*.12;
    s += place(foule, 0.);
    if(tf > 0. && tf < 1.5) pompe = min(pompe, 0.);

    float tc = t - (ARRIVEE + .4);
    if(tc > 0. && tc < DUREE - ARRIVEE - 2.){
        float pas = floor(tc/.13);
        float tl = tc - pas*.13;
        float dense = (tc < 5.8) ? 1. : .5;
        if(hasard(pas + 3.) < dense){
            float n = float(PENTATONIQUE[int(hasard(pas*1.7 + 1.)*4.99)]) + 12.*floor(hasard(pas + 9.)*2.);
            s += place(cloche(tl, freq(n, 1046.5), .07)*.07, hasard(pas + 5.)*1.6 - .8);
        }
    }

    float ap = t - ARRIVEE;
    if(ap > 1.5 && ap < 4.5){
        float approche = smoothstep(1.5, 4.5, ap);
        float pasP = floor(ap*6.);
        float ft = ap - pasP/6.;
        float tonPas = (mod(pasP, 2.) < 1.) ? 700. : 900.;
        float pas = (blancHaut()*.5 + sin(PI2*tonPas*ft)*.5)*env(ft, .001, .014)*.2*(.4 + .6*approche);
        s += place(pas, .8*(1. - approche) + .2);
    }
    s += place(cloche(ap - 4.5, 1318.5, .25)*.1 + cloche(ap - 4.65, 1568., .3)*.1, .2);

    for(int i = 0; i < 8; i++){
        float tl = ap - 5.2 - .11*float(i);
        float n = float(HARPE[i]);
        s += place(cloche(tl, freq(n, 523.25), .35)*.08, (mod(float(i), 2.) < 1.) ? -.4 : .4)*step(tl, 1.5);
    }

    float ta = ap - 6.2;
    float tada = cloche(ta, 1046.5, .9)*.1 + cloche(ta, 1318.5, .9)*.08 + cloche(ta, 1568., .9)*.08 + cloche(ta, 2093., 1.1)*.08;
    s += place(tada, 0.);
    if(ta > 0.) pompe = min(pompe, 1. - .5*exp(-ta*3.));

    if(ta > 0. && ta < DUREE - ARRIVEE - 6.2){
        float bj = mod(ta, .6283);
        float boing = sin(PI2*(260.*bj + 1100.*bj*bj))*env(bj, .002, .07)*.12*step(bj, .25);
        s += place(boing, 0.);
    }

    return s;
}

vec2 mainSound(int samp, float time)
{
    indexEchantillon = float(samp);
    graine = mod(indexEchantillon, 4093.) + 17.*mod(floor(indexEchantillon/4093.), 251.);
    pompe = 1.;
    float t = mod(time, DUREE);

    vec2 son = effets(t);
    son += moteur(t);
    son += musique(t)*pompe;
    son *= (1. - smoothstep(DUREE - 1.2, DUREE, t))*smoothstep(0., .03, t);
    son = son/(1. + .6*abs(son))*1.5;
    if(any(isnan(son)) || any(isinf(son))) son = vec2(0.);
    return son;
}
